    PatientDocumentsController_upload: {
        parameters: {
            query?: never;
            header?: {
                /** @description Sede activa. Sin ella, la sede principal. */
                "X-Location-Id"?: string;
            };
            path: {
                patientId: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description PDF, JPG, PNG, HEIC, DOCX o DICOM de hasta 20 MB
                     */
                    file: string;
                    category: components["schemas"]["PatientDocumentCategory"];
                    /** Format: date */
                    clinicalDate?: string;
                    /**
                     * @description Dientes FDI separados por comas
                     * @example 11,21
                     */
                    toothNumbers?: string;
                    notes?: string;
                };
            };
        };
        responses: {
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["PatientDocumentDto"];
                };
            };
            /** @description Falta el archivo, tipo no admitido, contenido que no coincide con su tipo, categoría, dientes, fecha o notas inválidos (mensaje en español) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Paciente no encontrado en esta clínica */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Este archivo ya está en la ficha del paciente. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description El archivo supera el máximo de 20 MB. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Hay demasiadas subidas en curso. Inténtalo de nuevo en unos segundos. / El almacén de archivos no responde. Inténtalo de nuevo en unos minutos. (con Retry-After) */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
